import numpy as np
from scipy.optimize import differential_evolution
import itertools

def objective(r):
    x = [1.0]
    curr = 1.0
    for val in r:
        curr *= val
        x.append(curr)

    min_diff = float('inf')
    # Pre-calculate all ratios
    ratios = []
    for i in range(5):
        for j in range(5):
            if i != j:
                ratios.append((i, j, x[i]/x[j]))

    # Find the minimum difference between two ratios using distinct indices
    for idx1 in range(len(ratios)):
        i1, j1, val1 = ratios[idx1]
        for idx2 in range(idx1 + 1, len(ratios)):
            i2, j2, val2 = ratios[idx2]
            if len({i1, j1, i2, j2}) == 4:
                diff = abs(val1 - val2)
                if diff < min_diff:
                    min_diff = diff
    return -min_diff

bounds = [(1.001, 10.0)] * 4
result = differential_evolution(objective, bounds, strategy='best1bin', popsize=20, mutation=(0.5, 1), recombination=0.7, tol=1e-8)
print(result.fun, result.x)

